//! Protobuf messages shared by the datastore and tracing store, generated by `build.rs` from
//! `webknossos-datastore/proto/*.proto` (proto2), plus conversions from the geometry types.
//!
//! prost decodes missing proto2 `required` scalar fields as their defaults, whereas ScalaPB
//! rejects such messages. Callers that need the strict behaviour must validate explicitly.

use crate::geometry::{BoundingBox, Vec3Double, Vec3Int};

/// Package `com.scalableminds.webknossos.datastore`.
#[allow(clippy::all, clippy::pedantic, missing_docs)]
pub mod datastore {
    include!(concat!(
        env!("OUT_DIR"),
        "/com.scalableminds.webknossos.datastore.rs"
    ));
}

use datastore::{BoundingBoxProto, Vec3DoubleProto, Vec3IntProto};

impl From<Vec3Int> for Vec3IntProto {
    fn from(Vec3Int { x, y, z }: Vec3Int) -> Self {
        Self { x, y, z }
    }
}

impl From<[i32; 3]> for Vec3IntProto {
    fn from([x, y, z]: [i32; 3]) -> Self {
        Self { x, y, z }
    }
}

impl From<[f64; 3]> for Vec3DoubleProto {
    fn from([x, y, z]: [f64; 3]) -> Self {
        Self { x, y, z }
    }
}

impl From<Vec3IntProto> for Vec3Int {
    fn from(Vec3IntProto { x, y, z }: Vec3IntProto) -> Self {
        Self::new(x, y, z)
    }
}

impl From<Vec3Double> for Vec3DoubleProto {
    fn from(Vec3Double { x, y, z }: Vec3Double) -> Self {
        Self { x, y, z }
    }
}

impl From<Vec3DoubleProto> for Vec3Double {
    fn from(Vec3DoubleProto { x, y, z }: Vec3DoubleProto) -> Self {
        Self::new(x, y, z)
    }
}

impl From<BoundingBox> for BoundingBoxProto {
    fn from(bounding_box: BoundingBox) -> Self {
        Self {
            top_left: bounding_box.top_left.into(),
            width: bounding_box.width,
            height: bounding_box.height,
            depth: bounding_box.depth,
        }
    }
}

impl From<BoundingBoxProto> for BoundingBox {
    fn from(proto: BoundingBoxProto) -> Self {
        Self::new(
            proto.top_left.into(),
            proto.width,
            proto.height,
            proto.depth,
        )
    }
}
